"""Final YouTube thumbnail generated by Puter.js / GPT Image 2.5 Sunburst with the Arabic phrase rendered natively.

``10_background.png`` (text-free, also the video background) goes in as the reference image; the model returns the
finished 1920x1080 image, kept as returned: nothing is drawn on it or resized afterwards. Free-only: the Node adapter
refuses to run unless the owner verified the account cannot be charged, and any failure here is reported to the caller,
which falls back to the existing free path. There is no paid fallback.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import tempfile
import time
from pathlib import Path

import sunburst_thumbnail as shared

MODEL = "openai/gpt-image-2.5-sunburst"
SECRET_NAME = "PUTER_AUTH_TOKEN"
FREE_ONLY_FLAG = "PUTER_FREE_ONLY_VERIFIED"
QUALITY = "medium"
ADAPTER = Path(__file__).resolve().parent / "generate_image_puter.mjs"
MAX_ATTEMPTS = shared.MAX_SUNBURST_THUMBNAIL_ATTEMPTS
STOP_CODES = {"PUTER_AUTH_MISSING", "PUTER_AUTH_FAILED", "PUTER_FREE_LIMIT", "PUTER_FREE_ONLY_NOT_GUARANTEED", "PUTER_BAD_ARGS"}
RETRYABLE = {"PUTER_REQUEST_FAILED", "PUTER_BAD_RESPONSE"}


class PuterError(RuntimeError):
    def __init__(self, code: str, detail: str = ""):
        super().__init__(f"{code}: {detail}" if detail else code)
        self.code = code


def enabled() -> bool:
    """Puter is only tried when a token exists and the owner has marked the account free-only verified."""
    return bool(os.environ.get(SECRET_NAME)) and os.environ.get(FREE_ONLY_FLAG) == "1"


def redact(text: str) -> str:
    token = os.environ.get(SECRET_NAME, "")
    return text.replace(token, "***") if token else text


def run_adapter(args: list[str], timeout: int) -> dict:
    """Run the Node adapter and return its single JSON line. Patched in tests."""
    done = subprocess.run(["node", str(ADAPTER), *args], capture_output=True, text=True, timeout=timeout,
                          env=os.environ.copy(), check=False)
    lines = [line for line in done.stdout.splitlines() if line.strip().startswith("{")]
    if not lines:
        raise PuterError("PUTER_REQUEST_FAILED", redact(done.stderr.strip()[-200:] or "adapter produced no result"))
    return json.loads(lines[-1])


def edit_image(prompt: str, reference_png: bytes, timeout: int = 600) -> bytes:
    if not os.environ.get(SECRET_NAME):
        raise PuterError("PUTER_AUTH_MISSING")
    with tempfile.TemporaryDirectory() as folder:
        work = Path(folder)
        (work / "reference.png").write_bytes(reference_png)
        (work / "prompt.txt").write_text(prompt, encoding="utf-8")
        try:
            result = run_adapter([str(work / "reference.png"), str(work / "prompt.txt"), str(work / "out.png"), QUALITY], timeout)
        except subprocess.TimeoutExpired as exc:
            raise PuterError("PUTER_REQUEST_FAILED", "adapter timed out") from exc
        if not result.get("ok"):
            raise PuterError(str(result.get("code", "PUTER_REQUEST_FAILED")), redact(str(result.get("detail", ""))))
        out = work / "out.png"
        if not out.is_file():
            raise PuterError("PUTER_BAD_RESPONSE", "no image file")
        return out.read_bytes()


def generate(story: Path, thumbnail_text: str, *, max_attempts: int = MAX_ATTEMPTS) -> dict:
    """Produce ``11_thumbnail_base.jpg``; stops at the first valid image and never exceeds 4 attempts."""
    if len(re.findall(r"[ء-ي]+", thumbnail_text)) not in (2, 3, 4):
        raise shared.ThumbnailError("THUMBNAIL_TEXT_FAILED: expected 2-4 Arabic words")
    reference = (story / shared.BACKGROUND_FILE).read_bytes()
    prompt = shared.build_prompt(thumbnail_text)
    attempts = min(int(max_attempts), MAX_ATTEMPTS)
    last_error = "no attempt made"
    for number in range(1, attempts + 1):
        record = {"attempt": number, "provider": "puter", "model": MODEL}
        try:
            image = shared.decode_image(edit_image(prompt, reference))
            shared.validate_thumbnail(image)
        except PuterError as exc:
            shared._log(story, {**record, "outcome": "error", "code": exc.code})
            if exc.code in STOP_CODES:
                raise
            last_error = exc.code
            time.sleep(min(5 * number, 20))
            continue
        except (OSError, ValueError, RuntimeError) as exc:
            shared._log(story, {**record, "outcome": "invalid_image", "detail": type(exc).__name__})
            last_error = "PUTER_INVALID_IMAGE"
            continue
        quality = shared.save_jpeg(image, story / shared.THUMBNAIL_FILE)
        shared._log(story, {**record, "outcome": "passed"})
        return {
            "thumbnail_generation_provider": "puter",
            "thumbnail_model": MODEL,
            "thumbnail_text_render_method": "native_in_generated_image",
            "thumbnail_attempts": number,
            "thumbnail_size": f"{shared.OUTPUT_SIZE[0]}x{shared.OUTPUT_SIZE[1]}",
            "thumbnail_generation_quality": QUALITY,
            "thumbnail_jpeg_quality": quality,
            "thumbnail_text_ocr_verified": False,  # no reliable Arabic OCR here: owner review is the final text check
        }
    raise PuterError("PUTER_REQUEST_FAILED", f"no valid thumbnail after {attempts} attempts ({last_error})")
